_CORE_SRC = '# Action format: [(from_node, to_node, unit_type, count), ...]\n# Payout: "if capacity_0 == capacity_1": each serves min(capacity_0, d / 2).\n# Otherwise the larger capacity serves min(capacity_big, d), and the smaller\n# serves min(capacity_small, d - served_big).\n# Cost: upkeep_p = 3.0 * (10 - heavy_p at own base)\n#                  + 1.0 * (20 - light_p at own base).\n# Moves precede payout; each unit may move only one edge per turn.\n\nimport heapq\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 70\nTYPES = ("heavy", "light")\nCAPACITY = (8, 3)\nUPKEEP = (3.0, 1.0)\n\n\ndef payout(own, opponent, demand):\n    """Exact revenue for both sides, before upkeep."""\n    if own == opponent:\n        served = min(own, demand / 2.0)\n        return served, served\n    if own > opponent:\n        first = min(own, demand)\n        return first, min(opponent, demand - first)\n    first = min(opponent, demand)\n    return min(own, demand - first), first\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    for a, b in edges:\n        adjacency[a].append(b)\n        adjacency[b].append(a)\n    for row in adjacency:\n        row.sort()\n    distances = []\n    for start in range(n):\n        row = [n + 1] * n\n        row[start] = 0\n        queue = deque([start])\n        while queue:\n            a = queue.popleft()\n            for b in adjacency[a]:\n                if row[b] == n + 1:\n                    row[b] = row[a] + 1\n                    queue.append(b)\n        distances.append(row)\n    hops = [[-1] * n for _ in range(n)]\n    for a in range(n):\n        for b in range(n):\n            if a != b:\n                for v in adjacency[a]:\n                    if distances[v][b] == distances[a][b] - 1:\n                        hops[a][b] = v\n                        break\n    return adjacency, distances, hops\n\n\ndef legal_action(have, want, adjacency, distances, hops):\n    """Closest-first pairing, followed by independent start-state validation."""\n    proposed = {}\n    n = len(adjacency)\n    for typ in range(2):\n        surplus = [max(0, have[typ][i] - want[typ][i]) for i in range(n)]\n        deficit = [max(0, want[typ][i] - have[typ][i]) for i in range(n)]\n        pairs = sorted(\n            (distances[a][b], a, b)\n            for a in range(n) if surplus[a]\n            for b in range(n) if deficit[b] and a != b\n        )\n        for _, a, b in pairs:\n            count = min(surplus[a], deficit[b])\n            hop = hops[a][b]\n            if count > 0 and hop >= 0:\n                surplus[a] -= count\n                deficit[b] -= count\n                key = (a, hop, typ)\n                proposed[key] = proposed.get(key, 0) + count\n\n    available = [list(row) for row in have]\n    result = []\n    for (a, b, typ), count in sorted(proposed.items()):\n        if not (0 <= a < n and 0 <= b < n and b in adjacency[a]):\n            continue\n        count = min(int(count), available[typ][a])\n        if count > 0:\n            available[typ][a] -= count\n            result.append((int(a), int(b), TYPES[typ], int(count)))\n    return result\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_data = None\n        self.base_demand = []\n        self.last_seen = []\n        self.last_counter = []\n        self.previous_plan = None\n        self.bad_reports = 0\n\n    def _forecast(self, obs, horizon):\n        n = obs["n_nodes"]\n        turn = obs.get("turn", 0)\n        demand = obs.get("demand", [None] * n)\n        counters = obs.get("surge_turns_left", [None] * n)\n        home = obs["player_base"]\n        enemy_home = obs["opponent_base"]\n        forecast = []\n        for v in range(n):\n            if demand[v] is not None:\n                counter = int(counters[v] or 0)\n                self.base_demand[v] = float(demand[v]) / (3 if counter else 1)\n                self.last_seen[v] = turn\n                self.last_counter[v] = counter\n            base = self.base_demand[v]\n            if v == home or v == enemy_home:\n                base = 0.0\n            row = []\n            for future in range(horizon):\n                elapsed = turn + future - self.last_seen[v]\n                if self.last_seen[v] < 0:\n                    probability = 0.271\n                elif elapsed < self.last_counter[v]:\n                    probability = 1.0\n                else:\n                    probability = 1.0 - 0.9 ** min(3, max(0, elapsed))\n                row.append((base, probability))\n            forecast.append(row)\n        return forecast\n\n    def _plan(self, obs, have, deadline):\n        n = obs["n_nodes"]\n        home = obs["player_base"]\n        adjacency, distances, hops = self.map_data\n        horizon = min(14, max(1, N_TURNS - int(obs.get("turn", 0))))\n        forecast = self._forecast(obs, horizon)\n        opponent = [\n            8 * obs["opponent_heavy"][v] + 3 * obs["opponent_light"][v]\n            for v in range(n)\n        ]\n        max_capacity = sum(8 * x for x in have[0]) + sum(3 * x for x in have[1])\n\n        # Integrated expected score difference, indexed by capacity and arrival\n        # delay. Evaluate the two demand outcomes separately: payout is nonlinear.\n        values = []\n        for v in range(n):\n            node_values = []\n            for capacity in range(max_capacity + 1):\n                suffix = [0.0] * (horizon + 1)\n                for t in range(horizon - 1, -1, -1):\n                    base, probability = forecast[v][t]\n                    a, b = payout(capacity, opponent[v], base)\n                    c, d = payout(capacity, opponent[v], round(3 * base, 1))\n                    suffix[t] = suffix[t + 1] + (\n                        (1 - probability) * (a - b) + probability * (c - d)\n                    )\n                node_values.append(suffix)\n            values.append(node_values)\n            if time.perf_counter() >= deadline:\n                return [list(row) for row in have]\n\n        remaining = [list(row) for row in have]\n        want = [[0] * n for _ in range(2)]\n        allocated_capacity = [0] * n\n        total = sum(map(sum, remaining))\n\n        # Priority queue is rebuilt after each placement. Priority service makes\n        # marginal values nonconcave at capacity crossings, so stale heap keys\n        # would be unsafe (unlike proportional-sharing games).\n        for _ in range(total):\n            if time.perf_counter() >= deadline:\n                break\n            heap = []\n            for typ in range(2):\n                unit_capacity = CAPACITY[typ]\n                upkeep = UPKEEP[typ]\n                for source in range(n):\n                    if not remaining[typ][source]:\n                        continue\n                    return_cost = upkeep * min(\n                        horizon, max(0, distances[source][home] - 1)\n                    )\n                    for target in range(n):\n                        distance = distances[source][target]\n                        delay = max(0, distance - 1)\n                        if target == home:\n                            gain = -return_cost\n                        elif delay >= horizon:\n                            continue\n                        else:\n                            current = allocated_capacity[target]\n                            table = values[target]\n                            gain = (\n                                table[current + unit_capacity][delay]\n                                - table[current][delay]\n                                - upkeep * horizon\n                            )\n                            # Small switching friction and persistent target\n                            # preference avoid chasing minor forecast changes.\n                            gain -= 0.22 * distance\n                            if source == target:\n                                gain += 0.12 * horizon\n                            if (\n                                self.previous_plan is not None\n                                and want[typ][target] < self.previous_plan[typ][target]\n                            ):\n                                gain += 0.08 * horizon\n                        priority = gain + return_cost\n                        heap.append((-priority, distance, typ, source, target))\n            if not heap:\n                break\n            heapq.heapify(heap)\n            _, _, typ, source, target = heapq.heappop(heap)\n            remaining[typ][source] -= 1\n            want[typ][target] += 1\n            allocated_capacity[target] += CAPACITY[typ]\n\n        # On budget exhaustion, leave unplanned units at their actual positions.\n        for typ in range(2):\n            for v in range(n):\n                want[typ][v] += remaining[typ][v]\n        return want\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0, 0.58 * TIME_BUDGET)\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0:\n            return []\n        if self.map_data is None:\n            self.map_data = preprocess_map(n, obs.get("edges", []))\n            self.base_demand = [3.8] * n\n            self.last_seen = [-1] * n\n            self.last_counter = [0] * n\n        if (\n            not obs.get("action_format_correct_last_turn", True)\n            or obs.get("n_invalid_actions_last_turn", 0) > 0\n        ):\n            self.bad_reports += 1\n        have = [\n            list(obs.get("player_heavy", [0] * n)),\n            list(obs.get("player_light", [0] * n)),\n        ]\n        if self.bad_reports >= 2:\n            # A persistent legality fault must not propagate into future turns.\n            return []\n        want = self._plan(obs, have, deadline)\n        adjacency, distances, hops = self.map_data\n        action = legal_action(have, want, adjacency, distances, hops)\n        self.previous_plan = [list(row) for row in want]\n        return action\n'
_CORE_CLASS = 'Strategy'
